input { flex: 1; min-width: 0; border: 1px solid #91a5af; border-radius: 6px; padding: 12px; font: inherit; }
button { border: 1px solid #91a5af; border-radius: 6px; background: white; color: #172c38; padding: 11px 16px; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #eaf1f4; }
button.primary { background: #146576; color: white; border-color: #146576; }
button.primary:hover { background: #104e5b; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #258da7; outline-offset: 3px; }
.project-list { margin-top: 32px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 18px 0; border-top: 1px solid #dce4e8; }
.project-row span { overflow-wrap: anywhere; min-width: 0; font-weight: 600; }
.project-row button { flex-shrink: 0; }
.project-details { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.project-details .summary { font-weight: 400; color: #536976; }
.project-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.alert { color: #a32323; }
.empty { color: #536976; }
.back { margin-bottom: 28px; }
.rename-form { margin-bottom: 28px; }
.task-filter, .project-filter { margin-top: 28px; }
select { border: 1px solid #91a5af; border-radius: 6px; padding: 10px 12px; background: white; color: inherit; font: inherit; }
.task-list { margin-top: 24px; }
.task-row { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; padding: 18px 0; border-top: 1px solid #dce4e8; }
.task-row input[type="checkbox"] { flex: 0 0 auto; width: 20px; height: 20px; margin: 0; accent-color: #146576; }
.task-row span { min-width: 0; overflow-wrap: anywhere; }
.task-rename-form { flex-basis: 100%; }
@media (max-width: 600px) { main { margin: 20px 12px; padding: 24px; } .controls { flex-direction: column; } .project-row { align-items: flex-start; flex-direction: column; } }

